-- ======================================================================== 20261027000014_chat_security_groups.sql
-- ---------------------------------------------------------------- audit trail of key and recovery activity (the member can read their own)
create table if not exists public.chat_key_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  action text not null check (action in ('create', 'rotate', 'recovery_key', 'passphrase', 'escrow_on', 'escrow_off', 'recovery_requested', 'recovery_cancelled', 'recovery_completed', 'recovery_failed')),
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists chat_key_events_user_idx on public.chat_key_events (user_id, created_at desc);
alter table public.chat_key_events enable row level security;
drop policy if exists chat_key_events_own on public.chat_key_events;
create policy chat_key_events_own on public.chat_key_events for select to authenticated using (user_id = auth.uid());
revoke all on public.chat_key_events from anon, authenticated;
grant select on public.chat_key_events to authenticated;
-- ---------------------------------------------------------------- backups: passphrase backup, recovery-key backup, escrow flag
alter table public.chat_key_backups add column if not exists recovery jsonb check (recovery is null or (jsonb_typeof(recovery) = 'object' and pg_column_size(recovery) < 4096));
alter table public.chat_key_backups add column if not exists escrow boolean not null default false;
-- VYBE-assisted recovery: the wrapped key lives in a table NO browser role can read; only the recovery Edge Function (service role) touches it.
create table if not exists public.chat_key_escrow (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  blob text not null check (char_length(blob) between 40 and 2000),
  created_at timestamptz not null default now()
);
alter table public.chat_key_escrow enable row level security;
revoke all on public.chat_key_escrow from anon, authenticated;
create table if not exists public.chat_recovery_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  status text not null default 'waiting' check (status in ('waiting', 'completed', 'cancelled', 'expired')),
  created_at timestamptz not null default now(),
  ready_at timestamptz not null,
  expires_at timestamptz not null,
  updated_at timestamptz not null default now(),
  ip_hash text
);
create unique index if not exists chat_recovery_one_active on public.chat_recovery_requests (user_id) where status = 'waiting';
create index if not exists chat_recovery_user_idx on public.chat_recovery_requests (user_id, created_at desc);
alter table public.chat_recovery_requests enable row level security;
drop policy if exists chat_recovery_own on public.chat_recovery_requests;
create policy chat_recovery_own on public.chat_recovery_requests for select to authenticated using (user_id = auth.uid());
revoke all on public.chat_recovery_requests from anon, authenticated;
grant select on public.chat_recovery_requests to authenticated;
-- Direct writes are closed: keys change only through the functions below (audited, rate-limited, owner alerted).
revoke insert, update, delete on public.chat_keys from authenticated;
drop policy if exists chat_keys_insert on public.chat_keys;
drop policy if exists chat_keys_update on public.chat_keys;
revoke insert, update, delete on public.chat_key_backups from authenticated;
drop policy if exists chat_key_backups_own on public.chat_key_backups;
create policy chat_key_backups_own on public.chat_key_backups for select to authenticated using (user_id = auth.uid());
create or replace function public.publish_chat_key(p_public text, p_backup jsonb, p_recovery jsonb default null) returns void
language plpgsql security definer set search_path = '' as $$
declare me uuid := auth.uid(); had boolean; recent integer;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if p_public !~ '^[A-Za-z0-9+/]{80,200}=*$' then raise exception 'Invalid key'; end if;
  if jsonb_typeof(p_backup) is distinct from 'object' or pg_column_size(p_backup) >= 4096 then raise exception 'Invalid backup'; end if;
  if p_recovery is not null and (jsonb_typeof(p_recovery) is distinct from 'object' or pg_column_size(p_recovery) >= 4096) then raise exception 'Invalid recovery backup'; end if;
  select count(*) into recent from public.chat_key_events where user_id = me and action in ('create', 'rotate') and created_at > now() - interval '1 hour';
  if recent >= 5 then raise exception 'Too many key changes. Please wait a while.'; end if;
  select exists (select 1 from public.chat_keys where user_id = me) into had;
  insert into public.chat_keys (user_id, public_key) values (me, p_public)
    on conflict (user_id) do update set public_key = excluded.public_key, updated_at = now();
  insert into public.chat_key_backups (user_id, backup, recovery, escrow) values (me, p_backup, p_recovery, false)
    on conflict (user_id) do update set backup = excluded.backup, recovery = excluded.recovery, escrow = false, updated_at = now();
  -- A new key makes the old escrow copy and any recovery in progress meaningless (and dangerous), so both go.
  delete from public.chat_key_escrow where user_id = me;
  update public.chat_recovery_requests set status = 'cancelled', updated_at = now() where user_id = me and status = 'waiting';
  insert into public.chat_key_events (user_id, action) values (me, case when had then 'rotate' else 'create' end);
  if had then perform public.notify(me, 'security', null, 'profile', me, 'ck:' || gen_random_uuid()); end if;
end $$;
-- Change the passphrase backup and/or the recovery-key backup of the key already published (the public key does not change).
create or replace function public.update_chat_backups(p_backup jsonb default null, p_recovery jsonb default null) returns void
language plpgsql security definer set search_path = '' as $$
declare me uuid := auth.uid(); recent integer;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if p_backup is null and p_recovery is null then return; end if;
  if (p_backup is not null and (jsonb_typeof(p_backup) is distinct from 'object' or pg_column_size(p_backup) >= 4096))
     or (p_recovery is not null and (jsonb_typeof(p_recovery) is distinct from 'object' or pg_column_size(p_recovery) >= 4096)) then raise exception 'Invalid backup'; end if;
  select count(*) into recent from public.chat_key_events where user_id = me and action in ('recovery_key', 'passphrase') and created_at > now() - interval '1 hour';
  if recent >= 10 then raise exception 'Too many changes. Please wait a while.'; end if;
  update public.chat_key_backups set backup = coalesce(p_backup, backup), recovery = coalesce(p_recovery, recovery), updated_at = now() where user_id = me;
  if not found then raise exception 'Turn on secure chat first'; end if;
  if p_backup is not null then insert into public.chat_key_events (user_id, action) values (me, 'passphrase'); end if;
  if p_recovery is not null then insert into public.chat_key_events (user_id, action) values (me, 'recovery_key'); end if;
  perform public.notify(me, 'security', null, 'profile', me, 'cb:' || gen_random_uuid());
end $$;
-- "This wasn't me": any signed-in device of the account can stop a recovery in progress.
create or replace function public.cancel_recovery_request(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.chat_recovery_requests set status = 'cancelled', updated_at = now() where id = p_id and user_id = auth.uid() and status = 'waiting';
  if not found then raise exception 'There is nothing to cancel'; end if;
  insert into public.chat_key_events (user_id, action) values (auth.uid(), 'recovery_cancelled');
end $$;
-- Service role only (the recovery Edge Function): records an event and alerts the member.
create or replace function public.chat_security_event(p_user uuid, p_action text, p_detail jsonb default '{}'::jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.chat_key_events (user_id, action, detail) values (p_user, p_action, coalesce(p_detail, '{}'::jsonb));
  if p_action in ('escrow_on', 'escrow_off', 'recovery_requested', 'recovery_completed') then
    perform public.notify(p_user, 'security', null, 'profile', p_user, 'cs:' || gen_random_uuid());
  end if;
end $$;
-- Expire stale requests whenever someone looks (no scheduler needed).
create or replace function public.expire_recovery_requests() returns void
language sql security definer set search_path = '' as $$
  update public.chat_recovery_requests set status = 'expired', updated_at = now() where status = 'waiting' and expires_at < now();
$$;
-- ---------------------------------------------------------------- end-to-end encrypted groups
alter table public.conversations add column if not exists key_epoch integer not null default 0 check (key_epoch >= 0);
create table if not exists public.conversation_keys (
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  epoch integer not null check (epoch >= 1),
  wrapped text not null check (char_length(wrapped) between 40 and 400),
  wrapped_by uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (conversation_id, user_id, epoch)
);
alter table public.conversation_keys enable row level security;
drop policy if exists conversation_keys_read on public.conversation_keys;
create policy conversation_keys_read on public.conversation_keys for select to authenticated using (user_id = auth.uid());
drop policy if exists conversation_keys_insert on public.conversation_keys;
create policy conversation_keys_insert on public.conversation_keys for insert to authenticated with check (
  wrapped_by = auth.uid()
  and exists (select 1 from public.conversation_members m where m.conversation_id = conversation_keys.conversation_id and m.user_id = auth.uid())
  and exists (select 1 from public.conversation_members t where t.conversation_id = conversation_keys.conversation_id and t.user_id = conversation_keys.user_id)
  and epoch <= (select c.key_epoch from public.conversations c where c.id = conversation_keys.conversation_id));
-- A member can drop their own row (e.g. a corrupted one) so that a member who holds the key can deliver it again.
drop policy if exists conversation_keys_delete on public.conversation_keys;
create policy conversation_keys_delete on public.conversation_keys for delete to authenticated using (user_id = auth.uid());
revoke all on public.conversation_keys from anon, authenticated;
grant select, insert, delete on public.conversation_keys to authenticated;
-- Turns encryption on for a group. Returns the current epoch and whether THIS call started it (only the starter makes and delivers the key).
-- If a start was abandoned before anyone received the key, the next call starts a fresh epoch, so a group can never be stuck without a key.
create or replace function public.start_group_encryption(p_conversation uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare e integer; made boolean := false;
begin
  if auth.uid() is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if not public.is_conversation_member(p_conversation) then raise exception 'You are not in this conversation'; end if;
  if not exists (select 1 from public.conversations where id = p_conversation and is_group) then raise exception 'Only group chats use group keys'; end if;
  select key_epoch into e from public.conversations where id = p_conversation for update;
  if e = 0 or not exists (select 1 from public.conversation_keys where conversation_id = p_conversation and epoch = e) then
    e := e + 1; made := true;
    update public.conversations set key_epoch = e where id = p_conversation;
    insert into public.chat_key_events (user_id, action, detail) values (auth.uid(), 'create', jsonb_build_object('group', p_conversation, 'epoch', e));
  end if;
  return jsonb_build_object('epoch', e, 'created', made);
end $$;
-- Who still needs the key for this epoch: members with a published key and no delivered copy yet.
create or replace function public.group_key_status(p_conversation uuid, p_epoch integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if not public.is_conversation_member(p_conversation) then raise exception 'You are not in this conversation'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('user_id', m.user_id, 'public_key', k.public_key))
    from public.conversation_members m join public.chat_keys k on k.user_id = m.user_id
    where m.conversation_id = p_conversation
      and not exists (select 1 from public.conversation_keys ck where ck.conversation_id = p_conversation and ck.user_id = m.user_id and ck.epoch = p_epoch)), '[]'::jsonb);
end $$;
-- Encrypted chats cannot be downgraded: an encrypted group only accepts encrypted messages, and encrypted messages never carry plain attachments.
alter table public.messages add column if not exists key_epoch integer check (key_epoch is null or key_epoch >= 1);
create or replace function public.trg_message_encryption() returns trigger
language plpgsql security definer set search_path = '' as $$
declare ce integer;
begin
  select key_epoch into ce from public.conversations where id = new.conversation_id;
  if new.e2ee and (new.media_path is not null or new.audio_path is not null) then raise exception 'Attachments in an encrypted chat must be encrypted'; end if;
  if coalesce(ce, 0) > 0 then
    if not new.e2ee then raise exception 'This chat is end-to-end encrypted. Turn on secure chat to take part.'; end if;
    if new.key_epoch is null or new.key_epoch > ce then raise exception 'Invalid group key'; end if;
  elsif new.key_epoch is not null then
    raise exception 'Invalid group key';
  end if;
  return new;
end $$;
drop trigger if exists message_encryption on public.messages;
create trigger message_encryption before insert on public.messages for each row execute function public.trg_message_encryption();
revoke execute on function public.publish_chat_key(text, jsonb, jsonb), public.update_chat_backups(jsonb, jsonb), public.cancel_recovery_request(uuid),
  public.start_group_encryption(uuid), public.group_key_status(uuid, integer), public.expire_recovery_requests() from public, anon;
grant execute on function public.publish_chat_key(text, jsonb, jsonb), public.update_chat_backups(jsonb, jsonb), public.cancel_recovery_request(uuid),
  public.start_group_encryption(uuid), public.group_key_status(uuid, integer), public.expire_recovery_requests() to authenticated;
revoke execute on function public.chat_security_event(uuid, text, jsonb) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.chat_security_event(uuid, text, jsonb) to service_role;
    grant select, insert, update, delete on public.chat_key_escrow, public.chat_recovery_requests, public.chat_key_events, public.chat_key_backups, public.chat_keys to service_role;
  end if;
end $$;

-- ======================================================================== 20261028000015_posts_names.sql
-- 15: posts with only a song, feeling or place; display-name changes limited to once every 14 days.
--
--  * posts_check required a caption or a photo, so a post with only a song (or only a feeling or place) was rejected with
--    'new row for relation "posts" violates check constraint "posts_check"'. The rule now accepts any real content.
--  * profiles.display_name_changed_at records the last name change; a trigger refuses another change within 14 days.
--    Onboarding (before onboarded_at is set) and server-side/admin updates (no auth.uid()) are not limited.
-- Non-destructive: no data is rewritten. Rollback: restore the old check and drop the trigger, function and column.

alter table public.posts drop constraint if exists posts_check;
alter table public.posts drop constraint if exists posts_has_content;
alter table public.posts add constraint posts_has_content check (
  body <> '' or media_path is not null or music_title is not null or music_path is not null
  or feeling is not null or place_name is not null
);
alter table public.profiles add column if not exists display_name_changed_at timestamptz;
create or replace function public.limit_display_name_change()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then
    return new;
  end if;
  if new.display_name is not distinct from old.display_name then
    new.display_name_changed_at := old.display_name_changed_at;
    return new;
  end if;
  if old.onboarded_at is null then
    return new;
  end if;
  if old.display_name_changed_at is not null and old.display_name_changed_at > now() - interval '14 days' then
    raise exception 'You can change your name again on %.', to_char(old.display_name_changed_at + interval '14 days', 'FMDD Mon YYYY')
      using errcode = 'check_violation', hint = 'name_cooldown';
  end if;
  new.display_name_changed_at := now();
  return new;
end $$;
revoke all on function public.limit_display_name_change() from public, anon, authenticated;
drop trigger if exists trg_limit_display_name on public.profiles;
create trigger trg_limit_display_name before update of display_name, display_name_changed_at on public.profiles
  for each row execute function public.limit_display_name_change();

-- ======================================================================== 20261029000016_campaigns.sql
-- 16: one campaign engine for two placements (Home billboard, Discover hero), honest labels, and organisation submissions.
--
--  * promo_slides gains placements (home and/or discover), a kind (sponsored | house | announcement) so VYBE's own promotions
--    are never labelled as paid, and an owning organisation for campaigns that organisations submit.
--  * State machine, enforced in the database (a client cannot make a campaign live by editing a field):
--      organisation owner/admin:  draft ⇄ submitted   (may edit, resubmit after a rejection, or delete their own until approved)
--      platform admin:            submitted → live (approved; "scheduled" while before starts_at) | rejected (with a reason)
--                                 live ⇄ paused, and anything else on platform-owned rows
--    Organisation rows are always "Sponsored", carry the organisation's own name as the advertiser, and their priority is set
--    by the admin who approves them. Reviews are written to audit_log and notify the organisation's owners and admins.
--  * Organisations upload creatives to brand/promo/o-<organisation id>/…; platform media stays under brand/promo/.
-- Additive: existing slides keep working (placements default to Home only, kind defaults to sponsored, no owner).
-- Rollback: drop the trigger/functions/policies below, then the added columns; restore the two original check constraints.

alter table public.promo_slides add column if not exists placements text[] not null default '{home}';
alter table public.promo_slides add column if not exists kind text not null default 'sponsored';
alter table public.promo_slides add column if not exists organization_id uuid references public.organizations(id) on delete cascade;
alter table public.promo_slides add column if not exists review_note text;
alter table public.promo_slides add column if not exists submitted_at timestamptz;
alter table public.promo_slides add column if not exists reviewed_by uuid references public.profiles(id) on delete set null;
alter table public.promo_slides add column if not exists reviewed_at timestamptz;
alter table public.promo_slides drop constraint if exists promo_slides_placements_check;
alter table public.promo_slides add constraint promo_slides_placements_check
  check (cardinality(placements) between 1 and 2 and placements <@ array['home','discover']::text[]);
alter table public.promo_slides drop constraint if exists promo_slides_kind_check;
alter table public.promo_slides add constraint promo_slides_kind_check check (kind in ('sponsored','house','announcement'));
alter table public.promo_slides drop constraint if exists promo_slides_review_note_check;
alter table public.promo_slides add constraint promo_slides_review_note_check check (review_note is null or char_length(review_note) <= 300);
alter table public.promo_slides drop constraint if exists promo_slides_status_check;
alter table public.promo_slides add constraint promo_slides_status_check check (status in ('draft','submitted','rejected','live','paused'));
alter table public.promo_slides drop constraint if exists promo_slides_media_path_check;
alter table public.promo_slides add constraint promo_slides_media_path_check
  check (media_path ~ '^promo/(o-[0-9a-f-]{36}/)?[0-9a-f-]{36}\.(jpg|png|webp|mp4|webm)$');
alter table public.promo_slides drop constraint if exists promo_slides_org_kind;
alter table public.promo_slides add constraint promo_slides_org_kind check (organization_id is null or kind = 'sponsored');
alter table public.promo_slides drop constraint if exists promo_slides_org_media;
alter table public.promo_slides add constraint promo_slides_org_media
  check (organization_id is null or media_path is null or media_path like 'promo/o-' || organization_id::text || '/%');
create index if not exists promo_slides_org_idx on public.promo_slides (organization_id) where organization_id is not null;
create index if not exists promo_slides_review_idx on public.promo_slides (status) where status = 'submitted';
-- True when the caller may manage campaigns for the organisation (owner or admin, active membership).
create or replace function public.can_manage_campaigns(oid uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select oid is not null and coalesce(public.org_role(oid) in ('owner','admin'), false);
$$;
revoke execute on function public.can_manage_campaigns(uuid) from public, anon;
grant execute on function public.can_manage_campaigns(uuid) to authenticated;
-- Members: live slides only (unchanged). Organisation managers: also every slide their organisation owns, at any stage.
drop policy if exists promo_read on public.promo_slides;
create policy promo_read on public.promo_slides for select to authenticated
  using (public.is_admin() or (status = 'live' and starts_at <= now() and (ends_at is null or ends_at > now()))
         or public.can_manage_campaigns(organization_id));
drop policy if exists promo_write on public.promo_slides;
create policy promo_write on public.promo_slides for insert to authenticated
  with check (public.is_admin() or (public.can_manage_campaigns(organization_id) and status in ('draft','submitted')));
drop policy if exists promo_edit on public.promo_slides;
create policy promo_edit on public.promo_slides for update to authenticated
  using (public.is_admin() or (public.can_manage_campaigns(organization_id) and status in ('draft','submitted','rejected')))
  with check (public.is_admin() or (public.can_manage_campaigns(organization_id) and status in ('draft','submitted')));
drop policy if exists promo_del on public.promo_slides;
create policy promo_del on public.promo_slides for delete to authenticated
  using (public.is_admin() or (public.can_manage_campaigns(organization_id) and status in ('draft','submitted','rejected')));
grant insert (placements, kind, organization_id) on public.promo_slides to authenticated;
grant update (placements, kind, review_note) on public.promo_slides to authenticated;
-- review_note is written by admins only (the trigger keeps the old value for anyone else); submitted_at, reviewed_by and
-- reviewed_at are only ever set by the trigger, and organization_id cannot change after insert.

-- Organisation managers may read their own campaign statistics.
drop policy if exists promo_stats_read on public.promo_stats;
create policy promo_stats_read on public.promo_stats for select to authenticated
  using (public.is_admin() or exists (select 1 from public.promo_slides s where s.id = slide_id and public.can_manage_campaigns(s.organization_id)));
create or replace function public.promo_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
declare admin boolean := public.is_admin(); org_name text;
begin
  if auth.uid() is null then return new; end if;                       -- server-side maintenance
  if tg_op = 'UPDATE' and new.organization_id is distinct from old.organization_id then
    raise exception 'A campaign cannot move to another organisation.' using errcode = '42501';
  end if;
  if new.organization_id is not null then
    select name into org_name from public.organizations where id = new.organization_id;
    new.advertiser := left(coalesce(org_name, ''), 80);                  -- the organisation can only advertise as itself
    new.kind := 'sponsored';
  end if;
  if not admin then
    if new.status not in ('draft','submitted') then
      raise exception 'Only VYBE can approve, publish, pause or reject a campaign.' using errcode = '42501';
    end if;
    new.priority := case when tg_op = 'UPDATE' then old.priority else 50 end;
    if tg_op = 'UPDATE' then new.review_note := old.review_note; new.reviewed_by := old.reviewed_by; new.reviewed_at := old.reviewed_at; end if;
    if new.status = 'submitted' and (tg_op = 'INSERT' or old.status is distinct from 'submitted') then new.submitted_at := now(); end if;
  else
    if tg_op = 'UPDATE' and new.status is distinct from old.status and new.status in ('live','rejected') and old.status in ('submitted','draft','rejected') then
      new.reviewed_by := auth.uid(); new.reviewed_at := now();
      if new.status = 'rejected' and coalesce(btrim(new.review_note), '') = '' then
        raise exception 'Give the organisation a reason when rejecting a campaign.' using errcode = '23514';
      end if;
      if new.status = 'live' then new.review_note := null; end if;
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;
revoke execute on function public.promo_guard() from public, anon, authenticated;
drop trigger if exists trg_promo_guard on public.promo_slides;
create trigger trg_promo_guard before insert or update on public.promo_slides for each row execute function public.promo_guard();
-- Reviews and state changes are audited; the organisation's owners and admins hear about approvals and rejections.
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check (type in
  ('friend_request', 'friend_accepted', 'reaction', 'comment', 'event_invite', 'rsvp', 'community_join', 'new_event', 'event_update', 'event_cancelled', 'live_started',
   'post_tag', 'memory_reaction', 'memory_reply', 'verified', 'security', 'campaign'));
create or replace function public.promo_audit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare m record;
begin
  if tg_op = 'INSERT' or new.status is distinct from old.status then
    insert into public.audit_log (actor, action, entity_type, entity_id, detail)
    values (auth.uid(), 'campaign.' || new.status, 'promo_slides', new.id,
            jsonb_build_object('from', case when tg_op = 'UPDATE' then old.status end, 'organization_id', new.organization_id, 'note', new.review_note));
    if tg_op = 'UPDATE' and new.organization_id is not null and new.status in ('live','rejected') and old.status in ('submitted','draft','rejected') then
      for m in select user_id from public.organization_members where organization_id = new.organization_id and status = 'active' and role in ('owner','admin') loop
        perform public.notify(m.user_id, 'campaign', auth.uid(), 'campaign', new.id, 'campaign:' || new.id || ':' || new.status || ':' || extract(epoch from now())::bigint);
      end loop;
    end if;
  end if;
  return null;
end $$;
revoke execute on function public.promo_audit() from public, anon, authenticated;
drop trigger if exists trg_promo_audit on public.promo_slides;
create trigger trg_promo_audit after insert or update on public.promo_slides for each row execute function public.promo_audit();
-- Creative uploads: platform admins under promo/, organisation managers under promo/o-<their organisation>/.
drop policy if exists brand_admin_insert on storage.objects;
create policy brand_admin_insert on storage.objects for insert to authenticated
  with check (
    (bucket_id in ('brand', 'brand-draft') and public.is_admin() and name ~ '^(hero|promo)/[0-9a-f-]{36}\.(jpg|png|webp|mp4|webm)$')
    or (bucket_id = 'brand' and name ~ '^promo/o-[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp|mp4|webm)$'
        and public.can_manage_campaigns(substring(name from '^promo/o-([0-9a-f-]{36})/')::uuid)));
drop policy if exists brand_org_delete on storage.objects;
create policy brand_org_delete on storage.objects for delete to authenticated
  using (bucket_id = 'brand' and name ~ '^promo/o-[0-9a-f-]{36}/'
         and public.can_manage_campaigns(substring(name from '^promo/o-([0-9a-f-]{36})/')::uuid));

-- ======================================================================== 20261030000017_profile_privacy.sql
-- 17: profile privacy. Until now any signed-in member could read every column of every (unblocked) profile, including
-- city-centre coordinates (lat/lng), notification settings, onboarding answers (intents, step), country and the onboarding
-- and name-change timestamps. Those are now readable only by their owner (through my_profile()) and by security-definer
-- functions that already need them (discovery distance, notifications). Row-level rules are unchanged.
--
-- Public columns (unchanged for everyone): id, username, display_name, bio, avatar_path, location, interests, dm_policy,
-- created_at, cover_path, verified_until, follow_policy, show_followers.
-- Rollback: grant select on public.profiles to authenticated;

revoke select on public.profiles from authenticated, anon;
grant select (id, username, display_name, bio, avatar_path, location, interests, dm_policy, created_at, cover_path, verified_until, follow_policy, show_followers)
  on public.profiles to authenticated;
-- Your own full profile row (all columns), for the app's session and the data export.
create or replace function public.my_profile() returns jsonb
language sql stable security definer set search_path = '' as $$
  select to_jsonb(p) from public.profiles p where p.id = auth.uid();
$$;
revoke execute on function public.my_profile() from public, anon;
grant execute on function public.my_profile() to authenticated;

-- ======================================================================== 20261031000018_media_policy_anon_helpers.sql
-- Migration 18 (written as "migration 14" on main, renumbered when the two branches were merged: this repository's
-- 20261027000014 is the chat security migration). Additive and re-runnable; no data is rewritten.
--
-- 1. Media read policy: in the lineup and community sub-queries the unqualified `name` bound to event_lineup.name and
--    communities.name (both tables have a `name` column), so `l.image_path = name` compared the image path with the act's own
--    name and never matched. Lineup images and community covers were therefore unreadable to everyone except their uploader.
--    Every reference is now qualified as objects.name. Nothing else changes: each sub-query still runs under the reader's RLS,
--    so a file is readable only when a row the reader may see points at it.
--
-- 2. (Removed in the merge.) Main's single `placement` and `label` columns are superseded by migration 16, which adds
--    `placements` (a slide may show in both places), `kind` and organisation campaigns. Keeping both would give the same
--    slide two contradicting sources of truth.
--
-- 3. Signed-out callers could run the visibility helpers over /rest/v1/rpc (the Supabase advisor flags 32 SECURITY DEFINER
--    functions executable by anon). Most only consult auth.uid() and return nothing useful to anon, but are_friends(a, b) and
--    is_blocked(a, b) answered for ANY two member ids. Anon has no table grants and no policy anon can reach calls these helpers,
--    so EXECUTE is moved from PUBLIC/anon to authenticated (and service_role). get_auth_hero() stays public: the signed-out
--    sign-in page needs it. Trigger functions are left alone (Postgres refuses to call them outside a trigger).
--
-- Rollback: re-run the media_select_visible block from 20261025000012_chat_calls_voice.sql, and grant execute on the 13 helpers
-- back to anon.

drop policy if exists media_select_visible on storage.objects;
create policy media_select_visible on storage.objects for select to authenticated
  using (
    bucket_id = 'media' and (
      (storage.foldername(objects.name))[1] = auth.uid()::text
      or exists (select 1 from public.posts p where p.media_path = objects.name or p.music_path = objects.name)
      or exists (select 1 from public.post_media pm where pm.path = objects.name)
      or exists (select 1 from public.comments c where c.audio_path = objects.name)
      or exists (select 1 from public.profiles pr where pr.avatar_path = objects.name or pr.cover_path = objects.name)
      or exists (select 1 from public.events e where e.cover_path = objects.name)
      or exists (select 1 from public.event_lineup l where l.image_path = objects.name)
      or exists (select 1 from public.communities c where c.cover_path = objects.name)
      or exists (select 1 from public.memories m where m.media_path = objects.name)
      or exists (select 1 from public.memory_replies r where r.audio_path = objects.name)
      or exists (select 1 from public.messages m where m.media_path = objects.name or m.audio_path = objects.name)
    )
  );
do $$
declare f text;
begin
  foreach f in array array[
    'public.are_friends(uuid, uuid)', 'public.is_blocked(uuid, uuid)', 'public.can_moderate_community(uuid)',
    'public.can_view_event(public.events)', 'public.can_view_memory(public.memories)', 'public.can_view_post(public.posts)',
    'public.community_is_public(uuid)', 'public.community_role(uuid)', 'public.has_feature(text, uuid)',
    'public.is_community_member(uuid)', 'public.is_conversation_member(uuid)', 'public.is_invited(uuid)', 'public.org_role(uuid)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
    if exists (select 1 from pg_roles where rolname = 'service_role') then execute format('grant execute on function %s to service_role', f); end if;
  end loop;
end $$;

commit;

-- Verification (read-only): every row should say ok = true.
select item, ok from (values
  ('14: chat key functions', exists (select 1 from pg_proc where proname = 'publish_chat_key') and exists (select 1 from pg_proc where proname = 'update_chat_backups')),
  ('14: group encryption', to_regclass('public.conversation_keys') is not null and exists (select 1 from pg_trigger where tgname = 'message_encryption')),
  ('14: recovery tables', to_regclass('public.chat_recovery_requests') is not null and to_regclass('public.chat_key_escrow') is not null and to_regclass('public.chat_key_events') is not null),
  ('15: posts_has_content replaces posts_check', exists (select 1 from pg_constraint where conname = 'posts_has_content') and not exists (select 1 from pg_constraint where conname = 'posts_check' and conrelid = 'public.posts'::regclass)),
  ('15: 14-day name rule', exists (select 1 from pg_trigger where tgname = 'trg_limit_display_name')),
  ('16: campaign columns', exists (select 1 from information_schema.columns where table_name = 'promo_slides' and column_name = 'placements')),
  ('16: campaign rules', exists (select 1 from pg_trigger where tgname = 'trg_promo_guard') and exists (select 1 from pg_trigger where tgname = 'trg_promo_audit')),
  ('16: notification types include security and campaign', pg_get_constraintdef((select oid from pg_constraint where conname = 'notifications_type_check')) like '%security%campaign%'),
  ('17: profiles private columns hidden', not has_column_privilege('authenticated', 'public.profiles', 'lat', 'select') and has_column_privilege('authenticated', 'public.profiles', 'display_name', 'select')),
  ('17: my_profile()', exists (select 1 from pg_proc where proname = 'my_profile')),
  ('18: media read rule reads objects.name in every sub-query', (select pg_get_expr(polqual, polrelid) from pg_policy where polname = 'media_select_visible') like '%l.image_path = objects.name%'),
  ('18: signed-out visitors cannot call the visibility helpers', not has_function_privilege('anon', 'public.are_friends(uuid, uuid)', 'execute') and has_function_privilege('authenticated', 'public.are_friends(uuid, uuid)', 'execute'))
) as v(item, ok);
